// .planning/audit/inventory/endpoints.csv is GENERATED by this script. Never hand-edit it:
// the next regeneration overwrites it. Corrections belong in inventory/endpoints.json.
/**
 * .planning/audit/tools/gen-endpoints-csv.mjs
 *
 * AUDIT-03 — the human-review view of the endpoint inventory. Reads
 * inventory/endpoints.json (its only input) and writes inventory/endpoints.csv so a
 * reviewer can sort and filter 94 route handlers in a spreadsheet.
 *
 * Usage: node .planning/audit/tools/gen-endpoints-csv.mjs
 *
 * The final column `no_auth_signal` is DERIVED, not stored: true when calls_get_user,
 * calls_verify_admin and calls_get_session are all false. Those rows are the
 * highest-value hand-review queue in the phase and are where plan 01-11 starts.
 *
 * The nearest CSV writer in this repo lives under `src/lib/` and is deliberately NOT
 * imported: a tool under .planning/ must not depend on an app-layer module
 * (01-PATTERNS.md § No Analog Found). The quote/escape rule is trivial and is
 * reimplemented inline below.
 *
 * Zero dependencies, ESM, node:fs only. Progress goes to stderr so stdout stays clean.
 */

import { readFileSync, existsSync, writeFileSync } from "node:fs";

const IN = ".planning/audit/inventory/endpoints.json";
const OUT = ".planning/audit/inventory/endpoints.csv";

/** Row-level columns, in output order. */
const ROW_COLUMNS = [
  "id", "route", "methods", "file",
];

/** Human-classification columns, in output order. */
const HUMAN_COLUMNS = [
  "auth_requirement", "role_required", "rls_reliance", "personalized",
  "input_validation", "test_present", "dead_or_duplicate",
  "cache_policy_today", "cache_policy_target",
];

/** Signal columns, in output order. `loc` is emitted earlier, next to `file`. */
const SIGNAL_COLUMNS = [
  "uses_cookie_client", "uses_service_client", "calls_verify_admin", "calls_get_user",
  "calls_get_session", "calls_check_ban", "inline_role_check", "references_club_members",
  "parses_body", "has_zod", "sets_cache_control", "cache_control_values",
  "env_vars_referenced", "has_try_catch", "catch_any_count", "console_count",
  "as_any_count", "tables_referenced",
];

const HEADER = [...ROW_COLUMNS, "loc", ...HUMAN_COLUMNS, ...SIGNAL_COLUMNS, "no_auth_signal"];

/**
 * RFC 4180 minimum: quote a field only when it carries a comma, a double quote or a
 * newline, and double any embedded double quote.
 */
function csvField(value) {
  const text = value === null || value === undefined
    ? ""
    : Array.isArray(value)
      ? value.join(";")            // arrays live in ONE cell, semicolon-separated
      : String(value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

async function main() {
  if (!existsSync(IN)) {
    console.error(`Run this from the repository root: ${IN} not found — run gen-endpoint-inventory.mjs first`);
    process.exit(1);
  }

  const rows = JSON.parse(readFileSync(IN, "utf8"));

  const lines = [HEADER.join(",")];
  for (const row of rows) {
    const s = row.signals ?? {};
    const noAuthSignal = s.calls_get_user === false && s.calls_verify_admin === false && s.calls_get_session === false;
    const cells = [
      ...ROW_COLUMNS.map((c) => csvField(row[c])),
      csvField(s.loc),
      ...HUMAN_COLUMNS.map((c) => csvField(row[c])),
      ...SIGNAL_COLUMNS.map((c) => csvField(s[c])),
      csvField(noAuthSignal),
    ];
    lines.push(cells.join(","));
  }

  writeFileSync(OUT, lines.join("\n") + "\n");
  const queue = lines.slice(1).filter((line) => line.endsWith(",true")).length;
  console.error(`wrote ${rows.length} rows to ${OUT}; ${queue} carry no authorization signal at all`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
